mapper.select:
SELECT post_date, end_date
FROM survey
WHERE seq = #{surveyId}

SELECT target_people AS targetCount
FROM survey
WHERE seq = #{surveySeq}

SELECT COUNT(DISTINCT a.participant_seq) AS participantsCount
FROM question q,
     answer a
WHERE q.survey_seq = #{surveySeq}
  AND q.seq = a.question_seq
  AND a.answer_date BETWEEN #{startDate} AND #{endDate}

SELECT seq AS answerSeq, participant_seq, answer_date AS answerDate, contents AS answerContent
FROM answer
WHERE question_seq = #{questionSeq}

SELECT f.*, -- a.seq AS answer_seq, a.participant_seq FROM (SELECT q.SEQ AS question_seq, q.NAME AS question_name, q.ORDER_NUM AS question_order_num, q.CC_SEQ AS cc_seq, c.NAME AS cc_name, qi.SEQ AS question_item_seq, qi.CONTENT AS question_item_content, qi.ORDER_NUM AS question_item_order_num FROM question q JOIN common_code c ON q.cc_seq = c.seq JOIN question_item qi ON q.seq = qi.question_seq WHERE q.survey_seq = #{surveySeq} AND c.parent_seq = 3) f LEFT JOIN answer a ON f.question_seq = a.question_seq AND (a.participant_seq IN
#{participantSeq}
AND f.question_item_content = a.contents) ORDER BY f.question_order_num, f.question_item_order_num
